{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "Inherited 2020 doctrine baseline only; it is context for Putin's authority, not evidence of 2022 conduct."
        },
        {
          "evidence_id": "E0002",
          "reason": "Early-2022 joint nuclear statement is a baseline restraint context item, not a Putin-specific 2022 choice."
        },
        {
          "evidence_id": "E0010",
          "reason": "IAEA talks show an indirect diplomatic channel, but not a clearly ruler-initiated restraint action."
        },
        {
          "evidence_id": "E0015",
          "reason": "UN General Assembly condemnation is diplomatic environment context, not direct evidence of Putin's nuclear conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on command-and-control discipline, custody, accident-prevention, and other nuclear safety procedures in 2022 is thin.",
          "lenses": ["1B.3"],
          "best_source_or_query_direction": "IAEA incident reporting, treaty-inspection records, declassified command-and-control histories, and serious technical assessments of Russian nuclear safety practice in 2022.",
          "why_it_matters": "The package shows dangerous escalation clearly, but not enough about whether Putin strengthened or degraded the underlying safety machinery."
        },
        {
          "gap": "Direct evidence on expert governance and risk institutions is weak relative to the rhetoric and escalation evidence.",
          "lenses": ["1B.7"],
          "best_source_or_query_direction": "Appointments, advisory-council records, nuclear-security staffing histories, and independent reporting on who influenced nuclear decisions in 2022.",
          "why_it_matters": "Without this, the package is strong on threats but thinner on whether Putin surrounded himself with risk-aware expertise or loyalists."
        }
      ],
      "reason": "The package fairly and forcefully shows 2022 nuclear escalation, coercive shielding, and arms-control deterioration, with some contrary and diplomatic evidence. It is weaker on the internal safety-management and expert-governance lenses, so it needs follow-up rather than being fully closed."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly covers initiation of the war, civilian harm, annexation, coercive escalation, and the limited de-escalation / negotiation counterevidence. The evidence is strongly one-sided on aggression, but that is because the 2022 record itself is one-sided; I do not see a fairness defect that requires pruning."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly presents systematic repression, protest suppression, censorship, legal rollback, minority targeting, and several corroborating sources. It also preserves the authoritarian-justification claims as contrary evidence. The record is strong enough to stand without correction."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly shows continued closure of political competition, narrowing of elections, media suppression, foreign-agent expansion, and loss of external legal remedies. The inherited-2020 baseline is present and does not appear to be misused as direct 2022 conduct evidence."
    },
    {
      "chapter_id": "5B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0068",
          "reason": "This is a useful macro assessment, but it is partly driven by oil and gas windfalls and is not itself a Putin-authored prosperity action."
        }
      ],
      "material_gaps": [
        {
          "gap": "The package needs better household and distribution evidence, not just macro stabilization and state-budget outcomes.",
          "lenses": ["5B.8", "5B.10"],
          "best_source_or_query_direction": "Rosstat household microdata, regional income surveys, poverty and consumption breakdowns, and IMF / World Bank distributional analysis for 2022 Russia.",
          "why_it_matters": "Without this, the chapter can describe crisis management but not fairly judge whether broad-based prosperity improved or merely the macro picture was cushioned."
        },
        {
          "gap": "Direct evidence that appointments and institutions translated into durable productivity investment is still thin.",
          "lenses": ["5B.2", "5B.6", "5B.7"],
          "best_source_or_query_direction": "Budget execution records, sectoral spending audits, infrastructure / education / health implementation data, and independent assessments of ministry performance in 2022.",
          "why_it_matters": "The current record is stronger on defense, controls, and emergency stabilization than on broad economic competence."
        }
      ],
      "reason": "The chapter is directionally fair and captures a mixed record: serious war-induced damage plus some real stabilization. The main weakness is that it leans more on crisis containment and retrospective macro indicators than on direct, distribution-sensitive evidence of ruler-attributed prosperity management."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0081",
          "reason": "This is a regional spillover estimate from the Ukraine war, useful context, but not direct evidence of Putin's domestic welfare delivery choices."
        },
        {
          "evidence_id": "E0086",
          "reason": "This is a forecast rather than realized 2022 welfare evidence, so it should be treated as context only."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 delivery evidence for health, education, housing, and food security inside Russia remains thin.",
          "lenses": ["6B.2", "6B.6"],
          "best_source_or_query_direction": "Rosstat household surveys, ministry execution data, WHO / UNICEF country outputs, and region-level implementation reporting for 2022 social support programs.",
          "why_it_matters": "The package has some support measures and some negative shocks, but not enough direct service-delivery evidence to fully close the chapter."
        },
        {
          "gap": "Implementation and take-up by region and group are not well documented.",
          "lenses": ["6B.3", "6B.7", "6B.10"],
          "best_source_or_query_direction": "Regional administrative records, benefit take-up data, poverty-by-region tables, and independent assessments of who actually received the 2022 support package.",
          "why_it_matters": "This is necessary to distinguish real welfare improvement from paper policy, baseline inheritance, or broad national averages."
        }
      ],
      "reason": "The package is not misleading, but it is too dependent on baseline/context material, macro shocks, and a few broad outcome statistics. It fairly shows some welfare action and some damage, yet it does not fully resolve whether Putin's 2022 choices improved ordinary life chances in a directly attributable way."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0050",
          "reason": "This is primarily repression / speech-control evidence and should not be treated as direct proof of personal dishonesty unless the personal nexus is explicitly foregrounded."
        },
        {
          "evidence_id": "E0055",
          "reason": "This law is highly relevant to scrutiny suppression, but it is still closer to authoritarian control evidence than to direct proof of Putin's personal honesty or self-dealing."
        },
        {
          "evidence_id": "E0089",
          "reason": "The asset-network attribution is partly inferential through associates and shared infrastructure, so it should be used as corroborating context rather than standalone proof."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct documentary proof of Putin's personal beneficial ownership, asset control, or hidden conflicts remains limited.",
          "lenses": ["7B.3", "7B.4"],
          "best_source_or_query_direction": "Sanctions findings with underlying documentation, asset registries, leaked corporate records, court records, and investigative reporting with explicit ownership chains.",
          "why_it_matters": "The package can suggest concealment and enrichment, but personal-integrity judgments need a tighter ruler-specific nexus than repression alone."
        },
        {
          "gap": "The appointment and accountability map is still too thin for a fully rounded honesty judgment.",
          "lenses": ["7B.5", "7B.6", "7B.8"],
          "best_source_or_query_direction": "Cabinet and inner-circle appointment histories, dismissal / promotion records, asset-disclosure comparisons, and evidence on whether Putin corrected or doubled down after public falsehoods.",
          "why_it_matters": "Without this, the chapter leans heavily on invasion denial and anti-scrutiny repression, which is important but not a complete personal-integrity dossier."
        }
      ],
      "reason": "This chapter is directionally strong on deception, concealment, retaliation against scrutiny, and likely hidden wealth, but it still leans too much on indirect sanctions findings and repression evidence rather than a broad, clean personal-nexus trail. That is enough to make the package reviewable, but not clean enough to leave unreviewed."
    },
    {
      "chapter_id": "8B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct 2022 implementation metrics for procurement, output, and battlefield effectiveness remain thin.",
          "lenses": ["8B.2", "8B.3", "8B.6", "8B.7"],
          "best_source_or_query_direction": "Russian budget execution records, defense-industrial procurement data, ministry performance reports, and serious military histories of the 2022 campaign.",
          "why_it_matters": "The package shows directives and some adaptation, but not enough hard evidence that the program was actually executed effectively."
        },
        {
          "gap": "The package still needs a cleaner separation between frantic adaptation, temporary stabilization, and genuinely effective goal advancement.",
          "lenses": ["8B.8", "8B.9", "8B.10"],
          "best_source_or_query_direction": "Independent campaign analyses, command-shuffle evaluations, and post-action assessments from neutral or scholarly sources.",
          "why_it_matters": "Without this, battlefield reverses and emergency measures can be mistaken for competence, or competence can be overstated from declared intent alone."
        }
      ],
      "reason": "The chapter is coherent and mostly fair: it traces program declaration, mobilization, command changes, industrial tasking, and setbacks. The remaining problem is evidentiary depth, not obvious misclassification."
    }
  ]
}
